mapper.select:
SELECT tp.tid,re.`name`,tp.doctor_code,re.birth_date,sp.*,setype.service_name,sas.`name` AS cname,sbs.`name` AS cbname,plan.plan_name,thdic.threshold_name FROM yh_jz_service_total_person tp LEFT JOIN yh_jz_service_person sp ON tp.user_code=sp.user_code LEFT JOIN yh_user_reginfo re on tp.user_code=re.user_code LEFT JOIN yh_user_enrolinfo enro ON enro.user_code=re.user_code LEFT JOIN yh_jz_service_type setype ON sp.service_type=setype.id LEFT JOIN yh_jz_service_assessment_switch sas ON sas.id=sp.childnodes LEFT JOIN yh_jz_service_bodydata_switch sbs ON sp.childnodes=sbs.id LEFT JOIN yh_jz_service_plan plan ON sp.childnodes=plan.id LEFT JOIN yh_threshold_dic thdic ON sp.childnodes=thdic.dic_id
and re.user_code=#{usercode}
AND sp.service_state=#{state}
AND sp.service_type=#{servicetype}
AND sp.returnvisit=#{returnvisit}
and sbs.id=#{typeson} and sp.childtag=1
and sas.id=(#{typeson}-100) and sp.childtag=2
and thdic.dic_id=(#{typeson}-200) and sp.childtag=4
ORDER BY sp.insert_time
LIMIT #{page},20

mapper.update:
update yh_jz_service_person
set service_state=1,start_service_time=(SELECT NOW()),finishi_doctor=#{Usercode}
where id=#{serviceid}
